void my_sha256(const uint8_t *data, size_t len, uint8_t out[32]) {
    uint32_t s[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint64_t bitlen = (uint64_t)len * 8;
    while (len >= 64) { compress(s, data); data += 64; len -= 64; }
    uint8_t buf[128];
    size_t rem = len;
    memcpy(buf, data, rem);
    buf[rem++] = 0x80;
    size_t padlen = (rem <= 56) ? (56 - rem) : (120 - rem);
    memset(buf + rem, 0, padlen);
    rem += padlen;
    for (int i=0;i<8;i++) buf[rem++] = (bitlen >> (56-8*i)) & 0xff;
    size_t off = 0;
    while (off < rem) { compress(s, buf + off); off += 64; }
    for (int i=0;i<8;i++) {
        out[i*4] = s[i]>>24; out[i*4+1]=s[i]>>16; out[i*4+2]=s[i]>>8; out[i*4+3]=s[i];
    }
}

static double now() { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec + t.tv_nsec/1e9; }

int main() {
