    printf("my_sha256: %.6f s, %.1f MB/s\n", (t1-t0)/reps, n/((t1-t0)/reps)/1e6);
    t0=now();
    for (int i=0;i<reps;i++) SHA256(data,n,out2);
    t1=now();
    printf("openssl:   %.6f s, %.1f MB/s\n", (t1-t0)/reps, n/((t1-t0)/reps)/1e6);
    return 0;
